def find_norm_rep(p: int, q: int, max_b: int = 200_000):
    """
    Find smallest (a, b) with a^2 - p b^2 = q, a, b > 0, gcd(a, b) = 1.
    Returns (a, b) or None if no such representation found within max_b.

    Existence: (q / p) = +1 implies q is a norm from some ideal class
    in Z[√p]; the principal class has a representation iff q lies in
    the trivial genus *and* the ambiguous-class structure permits.
    For genus-non-principal pairs we return None.
    """
    if p <= 0 or q <= 0:
        return None
    # Brute-force search.  For performance, exit on perfect square check.
    for b in range(1, max_b + 1):
        a_sq = q + p * b * b
        a = math.isqrt(a_sq)
        if a * a == a_sq and math.gcd(a, b) == 1:
            return (a, b)
    return None


def find_norm_rep_4q(p: int, q: int, max_b: int = 200_000):
    """
    Find (a, b) with a^2 - p b^2 = 4 q (alternative normalization).
    """
    target = 4 * q
    for b in range(1, max_b + 1):
        a_sq = target + p * b * b
        a = math.isqrt(a_sq)
        if a * a == a_sq:
            return (a, b)
    return None

